steps.script:
function transform(ctx) {
  var MAP = { "电信": "telecom", "校园网": "xyw" };
  var isp = (ctx.isp || "").trim();
  var s = isp ? (MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp.substring(1) : "")) : "";
  var full = (ctx.username || "") + (s ? "@" + s : "");
  return { ua: url_encode(",0," + full), ep: url_encode(ctx.password || "") };
}
